import React, {useState} from 'react';
import './App.css';


function App () {
  
  const [storage, setStorage] = useState([])
  const availableLoads = [
    {name: 'Family Fridge', load: 800, duration: 24},
    {name: 'Mini Fridge', load: 80, duration: 24},
    {name: 'Coffee Maker', load: 1200, duration: 0.2},
    {name: 'Curling Iron', load: 1400, duration: 0.2},
    {name: 'Hair Dryer', load: 2000, duration: 0.2},
    {name: 'Clothes Dryer', load: 3000, duration: 1},
    {name: 'Laptop', load: 60, duration: 5},
    {name: 'Phone', load: 20, duration: 2}
  ]


  function addLoad(item){
    let updatedStorage = [...storage]
    updatedStorage.push(item)
    setStorage(updatedStorage)
  }

  function removeLoad(item){
    let updatedStorage = [...storage]
    let remainingArr = updatedStorage.filter(data => data.name !== item.name)
    console.log(updatedStorage, remainingArr)
    setStorage(remainingArr)
  }

  function makeTotalWatts(){
    let total = 0
    storage.map(device => total += device.load)
    return total
  }

  function makeTotalBatteryUsage(){
    let total = 0
    storage.map(device => total += (device.load * device.duration))
    return total
  }

  return (
  <div className="App">
    <p>What do you need to run? Add elements below and see how big an inverter and battery you need.</p>     
    <div>{availableLoads.map(load => <button onClick={() => addLoad(load)}>{load.name}</button>)}</div>
    <div style={{marginBottom: 30}}>{storage.map(device => <div>{device.name}, {device.load}W for {device.duration} hours <button onClick={() => removeLoad(device)}>Remove</button></div>)}</div>
    <div><h3>Watts Available: {500 - makeTotalWatts()}W</h3></div>
    <div><h3>Battery Available: {540 - makeTotalBatteryUsage()}Wh</h3></div>
  </div>
)
}

export default App;